html:
{%- set blue = "#0f4c81" -%}
{%- set red = "#d71920" -%}
{%- set ink = "#1c2329" -%}
{%- set muted = "#5b6770" -%}
{%- macro m(v) -%}{{ "{:,.2f}".format(v or 0) }}{%- endmacro -%}
{%- set company = frappe.db.get_value("Company", doc.company, ["company_name", "tax_id", "email", "phone_no", "website", "default_bank_account"], as_dict=True) -%}
{%- set bank = frappe.db.get_value("Bank Account", company.default_bank_account, ["account_name", "bank", "bank_account_no", "branch_code"], as_dict=True) if company and company.default_bank_account else None -%}
{%- set matter = frappe.db.get_value("Legal Matter", doc.get("matter"), ["title", "court", "responsible_advocate"], as_dict=True) if doc.get("matter") else None -%}
{%- set is_tax = doc.taxes | length > 0 -%}
{%- set addr = (doc.company_address_display or "").replace("<br>", " · ").replace("\n", " ") -%}
<style>
.jf { font-size: 11px; color: {{ ink }}; }
.jf table { border-collapse: collapse; }
.jf .tag { display: inline-block; background: {{ blue }}; color: #fff; font-size: 9px; font-weight: 700; letter-spacing: 1px; padding: 3px 8px; margin-bottom: 5px; }
.jf .muted { color: {{ muted }}; }
.jf .num { text-align: right; white-space: nowrap; }
.jf .rule { border-bottom: 2px solid {{ blue }}; margin: 10px 0 22px; }
.jf .rule div { width: 110px; height: 0; border-bottom: 3px solid {{ red }}; margin-bottom: -2px; }
.jf .meta { border: 1px solid #d5dbe0; min-width: 270px; }
.jf .meta td { padding: 4px 10px; border-bottom: 1px solid #e6eaee; font-size: 10px; }
.jf .meta tr:last-child td { border-bottom: 0; }
.jf .meta td.k { background: #f4f6f8; color: {{ muted }}; letter-spacing: .5px; font-weight: 600; }
.jf .meta td.v { text-align: right; font-weight: 700; }
.jf .items { width: 100%; border: 1px solid #d5dbe0; margin-bottom: 20px; }
.jf .items th { background: {{ blue }}; color: #fff; font-size: 9px; letter-spacing: 1px; padding: 7px 8px; text-align: left; }
.jf .items th.num { text-align: right; }
.jf .items td { padding: 9px 8px; border-bottom: 1px solid #e6eaee; vertical-align: top; }
.jf .totals { width: 100%; border: 1px solid #d5dbe0; }
.jf .totals td { padding: 6px 10px; border-bottom: 1px solid #e6eaee; }
.jf .totals tr.grand td { font-weight: 700; font-size: 13px; border-top: 2px solid {{ blue }}; border-bottom: 0; }
</style>

<div class="jf">

  <table style="width:100%;">
    <tr>
      <td style="width:90px; vertical-align:middle;">
        <img src="/assets/jurisflow/images/jurisflow.svg" style="height:80px; max-width:90px;">
      </td>
      <td style="text-align:center; vertical-align:middle;">
        <div style="font-size:22px; font-weight:800; color:{{ blue }}; letter-spacing:.5px;">{{ (company.company_name or "") | upper }}</div>
        {%- if addr or company.tax_id %}
        <div class="muted" style="font-size:9.5px; margin-top:4px;">
          {{ addr }}{% if addr and company.tax_id %} &nbsp;|&nbsp; {% endif %}{% if company.tax_id %}{{ _("PIN") }}: {{ company.tax_id }}{% endif %}
        </div>
        {%- endif %}
        {%- if company.email or company.phone_no or company.website %}
        <div class="muted" style="font-size:9.5px;">
          {{ [company.phone_no, company.email, company.website] | select | join(" · ") }}
        </div>
        {%- endif %}
      </td>
      <td style="width:90px;"></td>
    </tr>
  </table>
  <div class="rule"><div></div></div>

  <table style="width:100%; margin-bottom:20px;">
    <tr>
      <td style="vertical-align:bottom;">
        <div style="font-size:24px; font-weight:800; letter-spacing:4px;">{{ _("TAX INVOICE") if is_tax else _("FEE NOTE") }}</div>
      </td>
      <td style="text-align:right; vertical-align:bottom;">
        <div class="muted" style="font-size:9px; letter-spacing:1px; font-weight:700;">{{ _("INVOICE NO.") }}</div>
        <div style="font-size:16px; font-weight:700; color:{{ blue }};">{{ doc.name }}</div>
      </td>
    </tr>
  </table>

  <table style="width:100%; margin-bottom:16px;">
    <tr>
      <td style="vertical-align:top;">
        <span class="tag">{{ _("INVOICE TO") }}</span>
        <div style="font-size:14px; font-weight:700;">{{ doc.customer_name }}</div>
        {%- if doc.tax_id %}<div class="muted" style="font-size:9.5px;">{{ _("TAX PIN") }} &nbsp; <b style="color:{{ ink }}">{{ doc.tax_id }}</b></div>{% endif %}
        {%- if doc.address_display %}<div class="muted">{{ doc.address_display }}</div>{% endif %}
      </td>
      <td style="vertical-align:top; width:280px;">
        <table class="meta" style="width:100%;">
          <tr><td class="k">{{ _("INVOICE DATE") }}</td><td class="v">{{ frappe.utils.formatdate(doc.posting_date, "dd MMM yyyy") }}</td></tr>
          <tr><td class="k">{{ _("PAYMENT DUE") }}</td><td class="v">{{ frappe.utils.formatdate(doc.due_date, "dd MMM yyyy") if doc.due_date else "" }}</td></tr>
          <tr><td class="k">{{ _("CURRENCY") }}</td><td class="v">{{ doc.currency }}</td></tr>
        </table>
      </td>
    </tr>
  </table>

  {%- if matter %}
  <div style="margin-bottom:16px;">
    <span class="tag">{{ _("MATTER") }}</span>
    <div style="font-weight:700;">{{ matter.title }}</div>
    <div class="muted">
      {{ doc.matter }}
      {%- if matter.court %} &middot; {{ matter.court }}{% endif %}
      {%- if matter.responsible_advocate %} &middot; {{ _("Advocate") }}: {{ frappe.db.get_value("User", matter.responsible_advocate, "full_name") or matter.responsible_advocate }}{% endif %}
    </div>
  </div>
  {%- endif %}

  <table class="items">
    <thead>
      <tr>
        <th style="width:5%;">#</th>
        <th>{{ _("DESCRIPTION OF SERVICES") }}</th>
        <th class="num" style="width:9%;">{{ _("QTY") }}</th>
        <th class="num" style="width:15%;">{{ _("RATE") }}</th>
        <th class="num" style="width:17%;">{{ _("AMOUNT") }} ({{ doc.currency }})</th>
      </tr>
    </thead>
    <tbody>
      {%- for row in doc.items %}
      <tr>
        <td>{{ loop.index }}</td>
        <td>
          <b>{{ row.item_name }}</b>
          {%- if row.description and row.description != row.item_name %}<div class="muted" style="font-size:10px;">{{ row.description }}</div>{% endif %}
        </td>
        <td class="num">{{ row.get_formatted("qty") }}</td>
        <td class="num">{{ m(row.rate) }}</td>
        <td class="num"><b>{{ m(row.amount) }}</b></td>
      </tr>
      {%- endfor %}
    </tbody>
  </table>

  <table style="width:100%;">
    <tr>
      <td style="vertical-align:top; padding-right:30px;">
        <span class="tag">{{ _("AMOUNT IN WORDS") }}</span>
        <div style="font-weight:700; font-size:11.5px;">{{ doc.in_words }}</div>
        {%- if is_tax %}<div class="muted" style="font-size:9px; margin-top:4px;">{{ _("VAT charged at 16% on the taxable value shown.") }}</div>{% endif %}
      </td>
      <td style="vertical-align:top; width:300px;">
        <table class="totals">
          <tr><td>{{ _("Subtotal") }}</td><td class="num">{{ m(doc.net_total) }}</td></tr>
          {%- for tax in doc.taxes %}
          <tr><td>{{ tax.description }}{% if tax.rate %} @ {{ tax.rate }}%{% endif %}</td><td class="num">{{ m(tax.tax_amount) }}</td></tr>
          {%- endfor %}
          <tr class="grand"><td>{{ _("Total") }} ({{ doc.currency }})</td><td class="num">{{ m(doc.grand_total) }}</td></tr>
          {%- if doc.outstanding_amount != doc.grand_total %}
          <tr><td>{{ _("Balance due") }}</td><td class="num">{{ m(doc.outstanding_amount) }}</td></tr>
          {%- endif %}
        </table>
      </td>
    </tr>
  </table>

  {%- if bank %}
  <div style="margin-top:22px;">
    <span class="tag">{{ _("PAYMENT DETAILS") }}</span>
    <div>{{ bank.account_name }} &middot; {{ bank.bank }}{% if bank.branch_code %} ({{ bank.branch_code }}){% endif %}</div>
    <div class="muted">{{ _("Account No.") }} {{ bank.bank_account_no }}</div>
  </div>
  {%- endif %}

  {%- if doc.terms %}<div class="muted" style="font-size:10px; margin-top:16px;">{{ doc.terms }}</div>{% endif %}
</div>
